CREATE   PROCEDURE Reporting.usp_NISI_BuildMonthlySnapshot @FromPeriod nvarchar(7), @ToPeriod nvarchar(7), @Verbose bit = 1 AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; IF @FromPeriod IS NULL OR @ToPeriod IS NULL OR LEN(@FromPeriod) <> 7 OR LEN(@ToPeriod) <> 7 OR SUBSTRING(@FromPeriod, 5, 1) <> N'_' OR SUBSTRING(@ToPeriod, 5, 1) <> N'_' BEGIN RAISERROR(N'Parametri periodo non validi. Formato atteso: YYYY_MM.', 16, 1); RETURN; END DECLARE @FromYear int = CAST(LEFT(@FromPeriod, 4) AS int); DECLARE @FromMonth int = CAST(SUBSTRING(@FromPeriod, 6, 2) AS int); DECLARE @ToYear int = CAST(LEFT(@ToPeriod, 4) AS int); DECLARE @ToMonth int = CAST(SUBSTRING(@ToPeriod, 6, 2) AS int); IF @FromMonth < 1 OR @FromMonth > 12 OR @ToMonth < 1 OR @ToMonth > 12 BEGIN RAISERROR(N'Mese non valido.', 16, 1); RETURN; END IF (@FromYear * 100 + @FromMonth) > (@ToYear * 100 + @ToMonth) BEGIN RAISERROR(N'@FromPeriod deve essere <= @ToPeriod.', 16, 1); RETURN; END INSERT INTO Reporting.NISI_BuildLog (FromPeriod, ToPeriod, Status) VALUES (@FromPeriod, @ToPeriod, N'RUNNING'); DECLARE @LogId int = SCOPE_IDENTITY(); IF @Verbose = 1 PRINT CONCAT(N'[NISI] LogId=', @LogId, N' avvio build da ', @FromPeriod, N' a ', @ToPeriod); BEGIN TRY DECLARE @CurYear int = @FromYear; DECLARE @CurMonth int = @FromMonth; DECLARE @TotalRows bigint = 0; WHILE (@CurYear * 100 + @CurMonth) <= (@ToYear * 100 + @ToMonth) BEGIN DECLARE @Periodo nvarchar(7) = CONCAT(@CurYear, N'_', RIGHT(N'0' + CAST(@CurMonth AS nvarchar(2)), 2)); DECLARE @FirstDay date = DATEFROMPARTS(@CurYear, @CurMonth, 1); DECLARE @AsOf date = EOMONTH(@FirstDay); IF @Verbose = 1 PRINT CONCAT(N'[NISI] periodo=', @Periodo, N' AsOf=', CONVERT(nvarchar(10), @AsOf, 23)); DELETE FROM Reporting.NISI_Snapshot WHERE Periodo = @Periodo; INSERT INTO Reporting.NISI_Snapshot ( Periodo, AsOfDate, CertificazioneId, SedeId, id_cert, ragsoc, codfisc, fiscalcode, companyname, [address], city, zipcode, issuedate, scope_ita, regulation, id_companysitetype, piva, region, istat_province_prcode, iso_country_alpha2, sector_code, sector_code_secondary_accredited, codente, ncertificate, BuildLogId ) SELECT t.periodo, @AsOf, TRY_CAST(t.id_cert AS int) AS CertificazioneId, (SELECT TOP 1 cs.SedeId FROM Certificazione.CertificazioneSede cs WHERE cs.CertificazioneId = TRY_CAST(t.id_cert AS int) AND cs.DataInizioValidita <= CAST(@AsOf AS datetime2(7)) AND cs.DataFineValidita > CAST(@AsOf AS datetime2(7)) AND cs.DataCancellazione IS NULL ORDER BY cs.CertificazioneSedeId) AS SedeId, t.id_cert, t.ragsoc, t.codfisc, t.fiscalcode, t.companyname, t.[address], t.city, t.zipcode, t.issuedate, t.scope_ita, t.regulation, t.id_companysitetype, t.piva, t.region, t.istat_province_prcode, t.iso_country_alpha2, t.sector_code, t.sector_code_secondary_accredited, t.codente, t.ncertificate, @LogId FROM Reporting.tvf_NISI_AtDate(@AsOf, @Periodo) AS t; SET @TotalRows = @TotalRows + @@ROWCOUNT; IF @CurMonth = 12 BEGIN SET @CurMonth = 1; SET @CurYear = @CurYear + 1; END ELSE SET @CurMonth = @CurMonth + 1; END UPDATE Reporting.NISI_BuildLog SET Status = N'SUCCESS', EndedAtUtc = SYSUTCDATETIME(), RowsWritten = @TotalRows WHERE LogId = @LogId; IF @Verbose = 1 PRINT CONCAT(N'[NISI] LogId=', @LogId, N' completato. Righe totali: ', @TotalRows); END TRY BEGIN CATCH DECLARE @ErrMsg nvarchar(4000) = ERROR_MESSAGE(); UPDATE Reporting.NISI_BuildLog SET Status = N'FAILED', EndedAtUtc = SYSUTCDATETIME(), Note = LEFT(@ErrMsg, 4000) WHERE LogId = @LogId; THROW; END CATCH END

GO

